import urllib.request,urllib.error,json,re
base="https://app.ontrackegy.com/saas/mobile/"
out={}
for url,label in [(base,"admin"),(base+"status_feed.php","status_feed")]:
 try:
  with urllib.request.urlopen(urllib.request.Request(url,headers={"User-Agent":"OnTrack-Control-Verification/1.0"}),timeout=8) as r:
   page=r.read(30000).decode("utf-8","replace")
   out[label+"_http"]=r.status
   if label=="admin":
    out["new_brand_visible"]="Operations & AI Call Control" in page
    out["no_public_settings"]="مفتاح الإدارة" in page and "إعدادات الإيجنت والصوت" not in page
 except urllib.error.HTTPError as e:out[label+"_http"]=e.code
print(json.dumps(out,ensure_ascii=False))
